    [200+Math.sin(t*0.25+6)*130,220+Math.cos(t*0.45+4)*80,0.13,1.4,4.0],
    [300+Math.cos(t*0.7+3)*90,100+Math.sin(t*0.35+5)*100,0.075,2.1,4.5]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
