  const r1=act-inh*0.7+bg*0.3+spiral;
  const r2=Math.tanh(r1*2.2);
  const feedback=Math.tanh(r2*1.5+harm*0.4)*0.9+Math.tanh(r2*0.8-harm*0.3)*0.1;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.25;
  const ring=Math.sin(dist*0.08-t*2)*Math.exp(-dist*0.005)*0.2;
